flow-diagram.createChart:
{
text = "The quick brown fox jumps over the lazy dog";
cell = css -> width -> reactFlowBorder(stroke: "#9aa7b4",
  content: reactFlowPosition(width: $width,
    content: reactFlowClipbox(cssClass: $css, content: reactFlowPadding(all: 4, content: reactFlowText($text)))));
clipRow = title -> css -> reactFlowVertical(gap: 4, contents: list(
  reactFlowText($title, fontWeight: "bold"),
  reactFlowHorizontal(gap: 12, contents: list(40, 80, 120, 160, 200).map(w -> $cell($css, $w)))));
reactFlowChart(
  fixedView: true,
  root: reactFlowPadding(all: 16, content: reactFlowVertical(gap: 16, contents: list(
    $clipRow("Without CSS class", null),
    $clipRow("All with the CSS class \"demo-clip-cell\"", "demo-clip-cell")))))
}

{
name = "A";
fill = "#73B1DD";
n = 60;
years = count(0, 2).map(y -> reactFlowGanttSpan(model: list("y", $y), rowModel: "year", start: $y * 360, end: $y * 360 + 360, canMove: false, canResize: false, canBeEdge: false,
  box: reactFlowBorder(top: false, bottom: false, right: false, stroke: "#9aa7b4",
    content: reactFlowSticky(reactFlowPadding(left: 4, content: reactFlowText($name + ": year " + ($y + 1), fontWeight: "bold"))))));
rows = count(0, $n).map(i -> reactFlowGanttRow(model: $i, label: reactFlowText($name + ": work package " + $i), borderColor: "#e4e8ec", rowPadding: 3, minContentHeight: 18));
bars = count(0, $n).map(i -> reactFlowGanttSpan(model: list("b", $i), rowModel: $i, start: ($i * 11) % 600, end: ($i * 11) % 600 + 90, canBeEdge: false,
  box: reactFlowFill(fill: $fill, content: reactFlowPadding(left: 4, content: reactFlowText($name + $i, fontSize: 10)))));
reactFlowChart(
  fixedView: true,
  root: reactFlowGantt(
    rootRows: concat(list(reactFlowGanttRow(model: "year", label: reactFlowText("Year", fontWeight: "bold"), acceptsDrop: false, backgroundColor: "#d3dde8", minContentHeight: 16)), $rows),
    items: concat($years, $bars),
    rangeMin: 0, rangeMax: 720, initialZoom: 3, frozenRows: 1))
}

{
name = "B";
fill = "#F2A65A";
n = 80;
years = count(0, 2).map(y -> reactFlowGanttSpan(model: list("y", $y), rowModel: "year", start: $y * 360, end: $y * 360 + 360, canMove: false, canResize: false, canBeEdge: false,
  box: reactFlowBorder(top: false, bottom: false, right: false, stroke: "#9aa7b4",
    content: reactFlowSticky(reactFlowPadding(left: 4, content: reactFlowText($name + ": year " + ($y + 1), fontWeight: "bold"))))));
rows = count(0, $n).map(i -> reactFlowGanttRow(model: $i, label: reactFlowText($name + ": work package " + $i), borderColor: "#e4e8ec", rowPadding: 3, minContentHeight: 18));
bars = count(0, $n).map(i -> reactFlowGanttSpan(model: list("b", $i), rowModel: $i, start: ($i * 7) % 600, end: ($i * 7) % 600 + 120, canBeEdge: false,
  box: reactFlowFill(fill: $fill, content: reactFlowPadding(left: 4, content: reactFlowText($name + $i, fontSize: 10)))));
reactFlowChart(
  fixedView: true,
  root: reactFlowGantt(
    rootRows: concat(list(reactFlowGanttRow(model: "year", label: reactFlowText("Year", fontWeight: "bold"), acceptsDrop: false, backgroundColor: "#d3dde8", minContentHeight: 16)), $rows),
    items: concat($years, $bars),
    rangeMin: 0, rangeMax: 720, initialZoom: 3, frozenRows: 1))
}
